import{_ as e,o as a,c as t,a3 as _}from"./chunks/framework.D8u9WiMi.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"examples/idea/账号定位.md","filePath":"examples/idea/账号定位.md"}'),r={name:"examples/idea/账号定位.md"};function s(o,p,A,I,n,d){return a(),t("div",null,[...p[0]||(p[0]=[_("<p>一、核心定位（最推荐，用于账号简介 / 置顶）</p><p>👉 一句话版本（最清晰）</p><p>帮职场人用 AI 提升效率、减少内耗，把时间换成成果。</p><p>二、稍微展开一点（用于公众号介绍 / 开篇说明）</p><p>👉 标准版（推荐）</p><p>这个号专注一件事：帮普通职场人用 AI 解决真实工作问题，比如写不完的材料、做不完的方案、重复性的低价值工作，以及不知道如何提升效率的困境。</p><p>三、更有“人味”的表达（适合做第一篇文章开头）</p><p>👉 故事感版本</p><p>如果你每天都在写不完的汇报、改不完的方案、做不完的表格，还总觉得时间不够用，那这个号就是写给你的——这里不讲虚的 AI 概念，只讲普通人怎么用 AI 少干活、少加班、甚至多赚一点。</p><p>四、精准一点（方便你后面做内容筛选）</p><p>👉 人群 + 问题 拆解版</p><p>服务对象：</p><p>普通打工人（运营、产品、销售、行政、内容岗） 想提升效率但不会用 AI 的人 想用 AI 副业但没方向的人</p><p>解决问题：</p><p>写作效率低（PPT / 汇报 / 文案） 重复性工作多（表格 / 整理 / 数据） 不会用 AI（不知道从哪里开始） 想变现但没路径 五、再往上一层（战略级表达）</p><p>👉 你这个号真正做的不是“教AI”，而是：</p><p>把 AI 变成职场人的“第二双手”。</p><p>六、非常关键的一点（一定要注意）</p><p>你现在这个定位已经很好了，但有一个容易踩的坑我必须提醒你：</p><p>👉 ❌ 不要做成：</p><p>“AI资讯号” “工具推荐号” “科技解读号”</p><p>👉 ✅ 要始终坚持：</p><p>“职场问题 → AI解决”</p><p>举个对比你就懂：</p><p>❌ 错：最近又出了一个很牛的AI工具 ✅ 对：这个AI工具，可以帮你10分钟写完周报 七、帮你直接定一个“选题判断标准”（超级实用）</p><p>以后你写任何一篇内容，都问自己一句话：</p><p>👉 “这篇内容，能不能帮一个职场人少花时间 or 多赚一点？”</p><p>能 → 发 不能 → 不发</p><p>这个标准会帮你筛掉 80% 的“看起来很对但没用”的内容</p><p>八、给你一个终极版本（我最推荐你用这个）</p><p>👉 最终定位（直接可用）</p><p>AI干货小馆：帮普通职场人用 AI 提高效率、减少内耗，把时间变成结果。</p>",32)])])}const l=e(r,[["render",s]]);export{c as __pageData,l as default};
